import React from "react";

export default function Footer(){
    const contactDetails=[
        {title:"Phone",content:"+44 07798850881"},
        {title:"Email",content:"kiranmavi5502@gmail.com"},
        {title:"Github",content:"https://github.com/Kiranmavi"},
        {title:"Let's Collaborate",content:"linkedin.com/in/kiran-mavi-188196215"},
        {title:"",content:"©2025 Kiran. Crafted with originality and purpose."},
    ]
    return(
        <div className="w-full h-full flex items-center justify-center flex-col gap-2">
            <div className="font-semibold text-2xl">Let&apos;s Keep the Story Going</div>
            {contactDetails.map((item,index)=>(
                <table className="flex w-[100%]">

                    <td className=" w-[40%] text-end">{item.title} :</td>
                    <td className={` font-bold ${index+1 === contactDetails.length ? 'w-[100%] text-center':'pl-4'}`}>{item.content}</td>
                </table>
            ))}


        </div>
    )
}
